INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("リリ", 1, 1, 0, 321, 24001, 1, 2, 40011, 125801, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n");
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("クリア", 2, 1, 0, 322, 24001, 1, 2, 40011, 126001, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます");
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("プレシア", 3, 1, 0, 323, 24001, 1, 2, 40011, 126101, "んーと。\nこれ、あげる。\nはい");
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("リリ", 4, 2, 0, 324, 24001, 1, 2, 40011, 125801, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します");
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("クリア", 5, 2, 0, 325, 24001, 1, 2, 40011, 126001, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです");
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("プレシア", 6, 2, 0, 326, 24001, 1, 2, 40011, 126101, "お兄。\nきてくれて、うれしい");
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("", 1, 0, 532001, 327, 91002, 100, 8, 80009, 0, "");
